{
  "events_to_add": [
    {
      "event_type": "system_update",
      "description": "Kai VPMには4つの人格（ariade、kai_pm_＊、eliot（予定）、kai_root）が定義され、各人格の責務・トーン・禁止事項が明文化された。Kai統括人格は監査・評価・改善のみに徹し、直接LLM生成リクエストは行わない。",
      "importance": "high"
    },
    {
      "event_type": "memory_mechanism_policy",
      "description": "Claude Codeローカル環境プロジェクトでは、記憶は/projets/{project_id}/memory/配下に時系列スナップショット（memory_{timestamp}.jsonl）とlogs/（会話ログ・差分記録）として保存し、記憶メカニズムは独立モジュール化・API化して共通利用。会話送信・新規作成時に自動保存し、保存ごとにgit add/commit/pushでGitHubへ反映。ファイル構造・命名・保存タイミング・バックアップ・トークン管理も明文化する方針。",
      "importance": "high"
    },
    {
      "event_type": "token_limit_policy",
      "description": "各AI機能ごとにトークン上限が定められている（例：Memory Chat β会話1000、Memory Update500、通常会話800、AI Project Manager1000、プロジェクト詳細生成2000、AI意図検出300-500、AI Context Manager300）。Memory Updateは圧縮・要約重視、プロジェクト詳細生成は情報量多い要約に活用、意図検出・要約系は構造をシンプルに設計することが推奨されている。",
      "importance": "high"
    },
    {
      "event_type": "design_focus",
      "description": "今後のmemory_layer_implementation設計では、トークン上限・自動保存・GitHub連携・バックアップ・ファイル命名/構造ルールの明確化が重点。各人格の責務分離とKai統括人格の監査専念、ユーザー指示や会話履歴・プロジェクト進捗の文脈活用も重視される。",
      "importance": "high"
    }
  ],
  "context_updates": {}
}

